def isbn_valid(s: str) -> bool:
    # Remove hyphens and spaces
    s = s.replace('-', '').replace(' ', '')

    if len(s) == 10:
        # First nine must be digits
        if not all('0' <= c <= '9' for c in s[:9]):
            return False
        # Last must be digit or uppercase X
        last = s[9]
        if not ('0' <= last <= '9' or last == 'X'):
            return False

        total = 0
        for i, ch in enumerate(s, start=1):
            if ch == 'X':
                value = 10
            else:
                value = int(ch)
            total += i * value
        return total % 11 == 0

    elif len(s) == 13:
        # All characters must be digits
        if not all('0' <= c <= '9' for c in s):
            return False

        total = 0
        for i, ch in enumerate(s, start=1):
            digit = int(ch)
            weight = 1 if i % 2 == 1 else 3
            total += weight * digit
        return total % 10 == 0

    return False
